const PLUGIN_NAME_MAX_LENGTH = 64;
const PLUGIN_NAME_PATTERN = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

export class PluginContextMismatchError extends Error {
  readonly reason = 'plugin_context_mismatch';

  constructor() {
    super(
      'A running Rivet process belongs to a different installation context. Keep it running until its work is finished, then stop that process explicitly before opening this installation.',
    );
    this.name = 'PluginContextMismatchError';
  }
}

export const getPluginName = (
  env: NodeJS.ProcessEnv = process.env,
): string | undefined => {
  const name = env.RIVET_PLUGIN_NAME;
  if (name === undefined) return undefined;
  if (
    name.length > PLUGIN_NAME_MAX_LENGTH ||
    name.trim() !== name ||
    !PLUGIN_NAME_PATTERN.test(name)
  ) {
    throw new Error(
      'RIVET_PLUGIN_NAME must be a lowercase hyphen-separated slug of at most 64 characters.',
    );
  }
  return name;
};

export const assertPluginContext = (
  actualName: string | undefined,
  env: NodeJS.ProcessEnv = process.env,
): void => {
  if (actualName !== getPluginName(env)) throw new PluginContextMismatchError();
};
